import importlib; import sys; 
if 'semver' in sys.modules:
    del sys.modules['semver']

import semver
parser = semver.createparser()

# Does parse_args(["--help"]) raise SystemExit?
try:
    parser.parse_args(["--help"])
    print("No exception")
except SystemExit as e:
    print(f"SystemExit({e.code})")
